// Müzik kutusu: düğme kutuyu açıp kapatır. Açıkken servo kapağı kaldırır,
// melodi çalar, LED yanar. Melodi: Beethoven "Sevinç Şarkısı" (telifsiz).
#include <Servo.h>

const int KAPAK_PIN = 2;
const int SERVO_PIN = 9;
const int BUZZER_PIN = 8;
const int LED_PIN = 11;
const int KAPALI_ACI = 0;
const int ACIK_ACI = 90;

Servo kapak;
bool acik = false;
int sonButon = HIGH;

// Nota frekansları ve süreleri (1 = onaltılık). 0 = es.
const int MELODI[] = {330, 330, 349, 392, 392, 349, 330, 294, 262, 262, 294, 330, 330, 294, 294};
const int SURE[]   = {4,   4,   4,   4,   4,   4,   4,   4,   4,   4,   4,   4,   4,   6,   2};
const int NOTA_SAYISI = sizeof(MELODI) / sizeof(MELODI[0]);
const int TEMPO = 150;  // ms; bir onaltılık nota

int nota = 0;
unsigned long notaBaslangic = 0;
int notaSuresi = 0;

void setup() {
  Serial.begin(9600);
  pinMode(KAPAK_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);
  kapak.attach(SERVO_PIN);
  kapak.write(KAPALI_ACI);
  delay(50);
  sonButon = digitalRead(KAPAK_PIN);  // açılış durumunu al; sahte ilk basışı önler
  Serial.println("Muzik kutusu hazir. Dugmeye bas.");
}

void loop() {
  int b = digitalRead(KAPAK_PIN);
  if (b == LOW && sonButon == HIGH) {
    acik = !acik;
    kapak.write(acik ? ACIK_ACI : KAPALI_ACI);
    digitalWrite(LED_PIN, acik);
    if (!acik) noTone(BUZZER_PIN);
    nota = 0;
    notaBaslangic = 0;
    notaSuresi = 0;
    Serial.println(acik ? "Kutu acildi" : "Kutu kapandi");
    delay(40);
  }
  sonButon = b;

  if (acik && millis() - notaBaslangic >= (unsigned long)notaSuresi) {
    if (MELODI[nota] > 0) tone(BUZZER_PIN, MELODI[nota], SURE[nota] * TEMPO);
    notaSuresi = SURE[nota] * TEMPO + 40;
    notaBaslangic = millis();
    nota = (nota + 1) % NOTA_SAYISI;  // bitince baştan
  }
  delay(5);
}
